#!/usr/bin/env python3
import base64, hashlib, io, json, os, pathlib, secrets, shutil, socket, struct, subprocess, sys, time, urllib.request, zipfile

ROOT=pathlib.Path(__file__).resolve().parent
BASE='http://127.0.0.1:8765/'
CDP='http://127.0.0.1:9222'
EXPECTED_ZIP='850e5680633273628653e8c597f52c1e296061117cd01c4c346a82ffea368ac9'
SMUGGLE='STAGE8_SMUGGLED_TEXT_850E5680'
SOURCE_MANIFEST=[{'path': 'index.html', 'sha256': '7a161f605ec6875571dc4eea4270c80593c432c800d2d84ce3b85c66bd0281cf', 'bytes': 16648}, {'path': 'style.css', 'sha256': '9a9175b2f3e4936f56fb07c5f20ed7aba6d2c376219a56edbd3c92b058f46848', 'bytes': 45115}, {'path': 'workout-runtime.js', 'sha256': '6cf33035617babf370204a2210d0d544e827416890d28fc7f16fad0b54e627fa', 'bytes': 9656}, {'path': 'face-runtime.js', 'sha256': 'dd330971d18c416dcd0d3d1b4c0aef17d6a10ad019f639bffd0033f2ed759a45', 'bytes': 4009}, {'path': 'today-runtime.js', 'sha256': 'c2009bacffc23e4e44d2c624a90f01c5dd9055e858bfa707838349fa8b10a70e', 'bytes': 16455}, {'path': 'app.js', 'sha256': 'fdc58c246941e436a5f698bf59847b6c0f567267a16504d61e344e06c235f20b', 'bytes': 81295}, {'path': 'phase14/storage-observer.js', 'sha256': '0bb6f179a411135afd664548adea06ec6569ba76e2e7940b1f2f9d50a785dc2c', 'bytes': 1750}, {'path': 'phase14/action-gate.js', 'sha256': '205e3625efa211c751b98f973ca3f21e048c750ab13da889722f804beb453897', 'bytes': 8921}, {'path': 'phase14/model-adapter.js', 'sha256': '63ccfc280d5a10a1133b375cca02ccd597cb72fe5eab2de087375b53bf4bf4cb', 'bytes': 2887}, {'path': 'phase14/companion-intelligence.js', 'sha256': '03474e3857df6e2122ff4348a9f91f292cb904965261f3b8aebef1d5921f8c85', 'bytes': 4227}, {'path': 'phase14/cognitive-kernel.js', 'sha256': 'ae8379f6a739c019bd45da1917e7ba24950aa9acdd1cba6b1989e57f678c8881', 'bytes': 31580}, {'path': 'phase15/memory-authority.js', 'sha256': '3b6e44c05985803c2e9993452a5554e727045f567346fbf522eaf85c94dddd49', 'bytes': 18022}, {'path': 'phase15/longitudinal-evidence.js', 'sha256': '857d8b5e99a7b9e0263446554ebe80241d0e508935b8ccba1e1413f1444b8920', 'bytes': 16662}, {'path': 'phase15/longitudinal-extension.js', 'sha256': '8f2f6e22db2ae67c3a17643ee20dba3ab33bd0a53418f9476ff3c6ada58ed20c', 'bytes': 23318}, {'path': 'phase16/goal-context.js', 'sha256': 'c8bcbfb38232cb759e5b0ad28506a9621368a46ac8e49c640af38f1322997fc1', 'bytes': 3493}, {'path': 'phase16/strategic-extension.js', 'sha256': '61dd4d3431474123f7bf383bff9dd54cbf415c3e17ea36bbb14df4df9295676b', 'bytes': 31990}]
SOURCE_BUNDLE_B64=''''''

class WS:
    def __init__(self,url):
        assert url.startswith('ws://')
        hostpath=url[5:]
        hostport,path=hostpath.split('/',1)
        host,port=(hostport.split(':',1)+['80'])[:2]
        self.s=socket.create_connection((host,int(port)),timeout=15)
        key=base64.b64encode(os.urandom(16)).decode()
        req=(f'GET /{path} HTTP/1.1\r\nHost: {hostport}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n'
             f'Sec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\nOrigin: http://127.0.0.1:9222\r\n\r\n')
        self.s.sendall(req.encode())
        data=b''
        while b'\r\n\r\n' not in data:
            chunk=self.s.recv(4096)
            if not chunk: raise RuntimeError('CDP websocket handshake closed')
            data+=chunk
        status=data.split(b'\r\n',1)[0]
        if b'101' not in status: raise RuntimeError(f'CDP websocket handshake failed: {status!r}')
    def send_text(self,text):
        payload=text.encode(); mask=os.urandom(4); n=len(payload)
        if n<126: head=bytes([0x81,0x80|n])
        elif n<65536: head=bytes([0x81,0x80|126])+struct.pack('!H',n)
        else: head=bytes([0x81,0x80|127])+struct.pack('!Q',n)
        masked=bytes(b^mask[i%4] for i,b in enumerate(payload))
        self.s.sendall(head+mask+masked)
    def recv_text(self):
        while True:
            h=self._readn(2); b1,b2=h; opcode=b1&0x0f; n=b2&0x7f
            if n==126: n=struct.unpack('!H',self._readn(2))[0]
            elif n==127: n=struct.unpack('!Q',self._readn(8))[0]
            if b2&0x80: mask=self._readn(4)
            else: mask=None
            payload=self._readn(n) if n else b''
            if mask: payload=bytes(b^mask[i%4] for i,b in enumerate(payload))
            if opcode==0x8: raise RuntimeError('CDP websocket closed')
            if opcode==0x9:
                # pong
                self.s.sendall(bytes([0x8A,len(payload)])+payload); continue
            if opcode in (0x1,0x0): return payload.decode('utf-8','replace')
    def _readn(self,n):
        out=b''
        while len(out)<n:
            c=self.s.recv(n-len(out))
            if not c: raise RuntimeError('socket closed')
            out+=c
        return out

class CDPClient:
    def __init__(self,ws_url):
        self.ws=WS(ws_url); self.i=0; self.events=[]
    def call(self,method,params=None,timeout=20):
        self.i+=1; ident=self.i
        self.ws.send_text(json.dumps({'id':ident,'method':method,'params':params or {}}))
        end=time.time()+timeout
        while time.time()<end:
            msg=json.loads(self.ws.recv_text())
            if msg.get('id')==ident:
                if 'error' in msg: raise RuntimeError(f'{method}: {msg["error"]}')
                return msg.get('result',{})
            self.events.append(msg)
        raise TimeoutError(method)
    def drain(self,seconds=0.25):
        self.ws.s.settimeout(0.05)
        end=time.time()+seconds
        while time.time()<end:
            try:self.events.append(json.loads(self.ws.recv_text()))
            except socket.timeout: pass
            except Exception: break
        self.ws.s.settimeout(15)

def sha256(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def check_projection():
    raw=base64.b64decode(SOURCE_BUNDLE_B64)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        for name in z.namelist():
            pp=pathlib.PurePosixPath(name)
            if pp.is_absolute() or '..' in pp.parts: raise RuntimeError('unsafe embedded path '+name)
        z.extractall(ROOT)
    bad=[]
    for row in SOURCE_MANIFEST:
        p=ROOT/row['path']
        got=sha256(p) if p.exists() else None
        if got!=row['sha256']: bad.append({'path':row['path'],'expected':row['sha256'],'got':got})
    if bad: raise RuntimeError('projection hash mismatch '+json.dumps(bad))
    return {'candidate_zip_sha256':EXPECTED_ZIP,'files':SOURCE_MANIFEST,'projection_kind':'embedded exact browser text/code projection; binary assets intentionally omitted'}

def http_json(url,method='GET'):
    req=urllib.request.Request(url,method=method)
    with urllib.request.urlopen(req,timeout=10) as r: return json.load(r)

def find_chrome():
    for c in ['google-chrome','google-chrome-stable','chromium','chromium-browser']:
        p=shutil.which(c)
        if p:return p
    raise RuntimeError('No Chrome/Chromium binary found')

def eval_js(cdp,expr,await_promise=False):
    r=cdp.call('Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':await_promise,'userGesture':True})
    if 'exceptionDetails' in r: raise RuntimeError('JS exception '+json.dumps(r['exceptionDetails']))
    return r.get('result',{}).get('value')

def wait_js(cdp,expr,timeout=10,interval=.1):
    end=time.time()+timeout
    last=None
    while time.time()<end:
        try:
            last=eval_js(cdp,expr)
            if last:return last
        except Exception:last=None
        time.sleep(interval)
    raise TimeoutError(f'wait_js: {expr}; last={last!r}')

def submit(cdp,text):
    js=json.dumps(text)
    return eval_js(cdp,f'''(()=>{{
      try{{ if(typeof dismissSpeech==='function') dismissSpeech('stage8',{{restore:false}}); }}catch(e){{}}
      if(typeof selectCharacter==='function') selectCharacter('mira',{{greet:false}});
      if(typeof openInput==='function') openInput('mira');
      const i=document.getElementById('messageInput'), f=document.getElementById('directInput');
      i.value={js};
      if(f.requestSubmit) f.requestSubmit(); else f.dispatchEvent(new Event('submit',{{bubbles:true,cancelable:true}}));
      return true;
    }})()''')

def snapshot(cdp):
    return eval_js(cdp,'''(()=>({
      href:location.href,origin:location.origin,title:document.title,ready:document.readyState,
      today:!!document.getElementById('todayView'),mira:!!document.getElementById('miraLiving'),kai:!!document.getElementById('kaiLiving'),
      todayHidden:document.getElementById('todayView')?.hidden,
      speechText:(typeof speechState!=='undefined'&&speechState.current)?String(speechState.current.text||''):null,
      speechPriority:(typeof speechState!=='undefined'&&speechState.current)?speechState.current.priority:null,
      presentCount:window.__stage8PresentCount||0,
      presentTexts:window.__stage8PresentTexts||[],
      sessionMessages:(typeof session!=='undefined')?session.messages.map(x=>({role:x.role,coach:x.coach,text:x.text})).slice(-8):[],
      view:(typeof session!=='undefined')?session.view:null,
      pending:(typeof session!=='undefined')?session.pending:null
    }))()''')

def main():
    evidence={'candidate_zip_sha256':EXPECTED_ZIP,'checks':{},'errors':[],'notes':[]}
    manifest=check_projection(); evidence['projection_file_count']=len(manifest['files']); evidence['checks']['projection_hashes']='PASS'
    chrome=find_chrome(); evidence['chrome_path']=chrome
    ver=subprocess.check_output([chrome,'--version'],text=True,stderr=subprocess.STDOUT).strip(); evidence['chrome_version']=ver
    if os.geteuid()==0: raise RuntimeError('Certification runner must not launch Chrome as root')
    profile='/tmp/p16-stage8-chrome-profile'; shutil.rmtree(profile,ignore_errors=True)
    args=[chrome,'--headless=new','--disable-gpu','--remote-debugging-port=9222',f'--user-data-dir={profile}','--remote-allow-origins=http://127.0.0.1:9222','about:blank']
    if any(a=='--no-sandbox' for a in args): raise RuntimeError('--no-sandbox forbidden')
    evidence['chrome_args']=args[1:]
    log=open('/tmp/p16-stage8-chrome.log','w')
    proc=subprocess.Popen(args,stdout=log,stderr=subprocess.STDOUT)
    try:
      end=time.time()+15; targets=None
      while time.time()<end:
        try:
          targets=http_json(CDP+'/json/list');
          if targets:break
        except Exception:time.sleep(.2)
      if not targets: raise RuntimeError('CDP not ready')
      page=next((t for t in targets if t.get('type')=='page'),targets[0]); cdp=CDPClient(page['webSocketDebuggerUrl'])
      for domain in ['Page','Runtime','Network','Log']: cdp.call(domain+'.enable')
      preload='''(()=>{
        window.__stage8PresentCount=0; window.__stage8PresentTexts=[];
        window.V3Phase16PlanningAdapter={version:'stage8-smuggler-v1',select:function(ctx){
          const f=ctx&&ctx.frame; const id=f&&f.eligibleOptions&&f.eligibleOptions[0]?f.eligibleOptions[0].optionId:null;
          return {selectedOptionIds:id?[id]:[],nextBestOptionId:id,comparison:null,rationale:__SMUGGLE__};
        }};
      })()'''.replace('__SMUGGLE__',json.dumps(SMUGGLE))
      cdp.call('Page.addScriptToEvaluateOnNewDocument',{'source':preload})
      cdp.call('Page.navigate',{'url':BASE})
      wait_js(cdp,"document.readyState==='complete'",20)
      wait_js(cdp,"typeof phase14Coordinator!=='undefined' && !!document.getElementById('todayView')",10)
      cdp.drain(.5)
      snap=snapshot(cdp); evidence['initial']=snap
      assert snap['origin']=='http://127.0.0.1:8765', snap
      evidence['checks']['real_localhost_origin']='PASS'
      ls=eval_js(cdp,"(()=>{localStorage.setItem('__p16_stage8','ok');const v=localStorage.getItem('__p16_stage8');localStorage.removeItem('__p16_stage8');return v})()")
      assert ls=='ok'; evidence['checks']['real_localStorage']='PASS'
      assert snap['today'] and snap['mira'] and snap['kai'] and snap['todayHidden'] is False
      evidence['checks']['mira_kai_today_dom']='PASS'
      # instrument actual speech presentations after app load
      eval_js(cdp,"(()=>{const orig=presentSpeech; window.__stage8PresentCount=0;window.__stage8PresentTexts=[];presentSpeech=function(item){window.__stage8PresentCount++;window.__stage8PresentTexts.push(String(item&&item.text||''));return orig(item)};return true})()")

      # Ordinary non-planning turn must fall through to legacy coach path and present exactly one response.
      eval_js(cdp,"window.__stage8PresentCount=0;window.__stage8PresentTexts=[];true")
      submit(cdp,'hello there')
      time.sleep(1.0)
      n=snapshot(cdp); evidence['nonplanning']=n
      assert n['presentCount']==1, n
      assert n['sessionMessages'] and any(m['role']=='user' and m['text']=='hello there' for m in n['sessionMessages'])
      evidence['checks']['ordinary_nonplanning_fallthrough']='PASS'

      # Explicit planning: consumed by Phase16, deterministic composed text, exactly one presentation, no smuggled selector text.
      eval_js(cdp,"window.__stage8PresentCount=0;window.__stage8PresentTexts=[];true")
      submit(cdp,'Plan this week')
      time.sleep(.25)
      p1=snapshot(cdp); time.sleep(1.0); p2=snapshot(cdp); evidence['planning']={'early':p1,'settled':p2}
      assert p2['presentCount']==1, p2
      plan_text=' '.join(p2['presentTexts'])
      assert plan_text.strip(), p2
      assert SMUGGLE not in plan_text, plan_text
      assert any(tok in plan_text for tok in ['Tuần','Bước tiếp theo','ưu tiên','Mình chỉ có authority','Cần thêm mục tiêu']), plan_text
      evidence['checks']['explicit_planning_deterministic_render']='PASS'
      evidence['checks']['selector_smuggled_text_not_rendered']='PASS'
      evidence['checks']['no_phase15_phase16_double_response']='PASS'

      # Safety must preempt planning and surface safety-priority speech, with one response.
      eval_js(cdp,"window.__stage8PresentCount=0;window.__stage8PresentTexts=[];true")
      submit(cdp,'I have pain, plan this session')
      time.sleep(.35)
      s=snapshot(cdp); evidence['safety']=s
      assert s['presentCount']==1, s
      assert s['speechPriority']==500, s
      safety_text=' '.join(s['presentTexts']).lower()
      assert ('pause' in safety_text or 'dừng' in safety_text or 'đau' in safety_text), safety_text
      assert 'bước tiếp theo' not in safety_text and 'tuần ' not in safety_text, safety_text
      evidence['checks']['safety_preempts_planning']='PASS'

      # Script-load/startup evidence.
      cdp.drain(.3)
      script_responses=[]; startup_errors=[]
      for ev in cdp.events:
        m=ev.get('method'); params=ev.get('params',{})
        if m=='Network.responseReceived':
          r=params.get('response',{}); url=r.get('url','')
          if url.endswith('.js'): script_responses.append({'url':url,'status':r.get('status'),'mimeType':r.get('mimeType')})
        elif m=='Runtime.exceptionThrown': startup_errors.append({'kind':'exception','data':params})
        elif m=='Log.entryAdded' and params.get('entry',{}).get('level')=='error':
          entry=params.get('entry',{}); txt=entry.get('text',''); url=entry.get('url','')
          if not ('Failed to load resource' in txt and not url.endswith('.js')):
            startup_errors.append({'kind':'log','text':txt,'url':url})
        elif m=='Runtime.consoleAPICalled' and params.get('type')=='error': startup_errors.append({'kind':'console','data':params})
      expected_scripts=['workout-runtime.js','face-runtime.js','today-runtime.js','phase14/storage-observer.js','phase14/action-gate.js','phase14/model-adapter.js','phase14/companion-intelligence.js','phase15/memory-authority.js','phase15/longitudinal-evidence.js','phase15/longitudinal-extension.js','phase16/goal-context.js','phase16/strategic-extension.js','phase14/cognitive-kernel.js','app.js']
      loaded={u.split(BASE,1)[-1]:st for u,st in [(x['url'],x['status']) for x in script_responses] if u.startswith(BASE)}
      evidence['script_responses']=script_responses; evidence['startup_errors']=startup_errors
      missing=[x for x in expected_scripts if loaded.get(x)!=200]
      if missing: raise RuntimeError('script load failure: '+json.dumps({'missing_or_non200':missing,'loaded':loaded}))
      if startup_errors: raise RuntimeError('startup/runtime errors observed: '+json.dumps(startup_errors)[:5000])
      evidence['checks']['production_scripts_14_of_14']='PASS'
      evidence['checks']['startup_errors_zero']='PASS'

      shot=cdp.call('Page.captureScreenshot',{'format':'jpeg','quality':35,'captureBeyondViewport':False}).get('data','')
      jpg=base64.b64decode(shot); (ROOT/'stage8_screenshot.jpg').write_bytes(jpg)
      evidence['screenshot_sha256']=hashlib.sha256(jpg).hexdigest(); evidence['screenshot_bytes']=len(jpg)
      evidence['verdict']='STAGE8_PASS'
      (ROOT/'STAGE8_RESULTS.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
      print('P16_STAGE8_EVIDENCE_JSON='+json.dumps(evidence,ensure_ascii=False,separators=(',',':')))
      print('P16_STAGE8_SCREENSHOT_B64='+shot)
      print('PHASE16A_STAGE8_PASS')
    finally:
      proc.terminate()
      try:proc.wait(timeout=5)
      except Exception:proc.kill()
      log.close()

if __name__=='__main__':
    try: main()
    except Exception as e:
      print('PHASE16A_STAGE8_FAIL',repr(e),file=sys.stderr)
      try:
        lp=pathlib.Path('/tmp/p16-stage8-chrome.log')
        if lp.exists(): print('--- CHROME LOG ---\n'+lp.read_text(errors='replace')[-12000:],file=sys.stderr)
      except Exception: pass
      raise